mapper.select:
SELECT dimension,reported FROM agent_runtime_budget_attempt_amounts
WHERE tenant_id=#{tenant} AND attempt_id=#{attempt} AND dimension IN
#{a.dimension}

mapper.update:
UPDATE agent_runtime_budget_balances
SET reserved=reserved+CASE dimension
WHEN #{a.dimension} THEN #{a.reserved}
ELSE 0 END,
maximum=CASE WHEN scope_kind='STAGE' AND policy_mode='ENFORCED' THEN CASE dimension
WHEN #{a.dimension} THEN #{a.maximum}
ELSE maximum END ELSE maximum END
WHERE tenant_id=#{tenant}
  AND dimension IN
#{a.dimension}
  AND ((scope_kind='ROOT' AND scope_id=#{root})
    OR (scope_kind IN ('RUN','STAGE') AND scope_id=#{run}))

UPDATE agent_runtime_budget_balances
SET consumed=consumed+CASE dimension
WHEN #{a.dimension} THEN #{a.reported}
ELSE 0 END,
reserved=reserved-CASE dimension
WHEN #{a.dimension} THEN #{a.reserved}
ELSE 0 END
WHERE tenant_id=#{tenant}
  AND dimension IN
#{a.dimension}
  AND ((scope_kind='ROOT' AND scope_id=#{root})
    OR (scope_kind IN ('RUN','STAGE') AND scope_id=#{run}))

UPDATE agent_runtime_budget_balances
SET maximum=CASE dimension
WHEN #{a.dimension} THEN #{a.maximum}
ELSE maximum END
WHERE tenant_id=#{tenant}
  AND dimension IN
#{a.dimension}
  AND ((scope_kind='CLOSING' AND scope_id=#{root})
    OR (scope_kind='CLOSING_RUN' AND scope_id=#{run}))
